package android.content;import java.util.Objects;public class ComponentName {public final String pkg,name;public ComponentName(String p,String n){pkg=p;name=n;}public static ComponentName unflattenFromString(String s){int i=s.indexOf('/');if(i<1||i==s.length()-1)return null;String p=s.substring(0,i),n=s.substring(i+1);return new ComponentName(p,n.startsWith(".")?p+n:n);}public String flattenToString(){return pkg+"/"+name;}public String getPackageName(){return pkg;}public String getClassName(){return name;}public boolean equals(Object o){return o instanceof ComponentName c&&Objects.equals(pkg,c.pkg)&&Objects.equals(name,c.name);}public int hashCode(){return Objects.hash(pkg,name);}}